"""Original public camera-framing exercise, illustrated with new AI examples."""
from html import escape
PATH='/tutorials/camera-framing/'
ART='/assets/notes/camera-framing-triptych-v1.webp'
TITLE_KO='같은 장면, 어디까지 보여줄까?'
TITLE_EN='Same scene. How much should you show?'

def teaser(t):
    return f'''<a class="tutorial-preview" href="{PATH}"><img src="{ART}" width="1672" height="941" loading="lazy" decoding="async" alt="{t('같은 인물과 안뜰을 원경·중경·근경으로 비교하는 카메라 구도 AI 실습 예시','AI camera-framing example comparing a wide, medium and close-up view of one character in a courtyard')}"><div><p class="section-eyebrow">CAMERA / WIDE · MEDIUM · CLOSE-UP</p><h3>{t(TITLE_KO,TITLE_EN)}</h3><p class="tutorial-card-date"><time datetime="2026-10-12">2026.10.12</time> · {t('카메라 구도 · 장면 연결 · 실습','Camera framing · Shot continuity · Practice')}</p><span>{t('원경·중경·근경 입문 · 강좌 열기','Wide, medium and close-up basics · Open lesson')} →</span></div></a>'''

def build(out,origin,head,header,footer,t):
    title=t(TITLE_KO,TITLE_EN)
    desc=t('원경·중경·근경을 언제 쓰는지, 인물·행동·공간을 어떻게 나누는지 배우는 AI 영화 카메라 구도 입문. 씬 예시와 전체 실습 프롬프트를 제공합니다.','A beginner AI filmmaking exercise on wide, medium and close-up shots: decide how much character, action and space to reveal, with scene examples and complete practice prompts.')
    steps=[
    ('01 / WIDE','원경: 어디에 있는지부터 보여줍니다.','Wide: establish where the scene happens.',
    '첫 번째 예시는 신발까지 보이는 인물과 안뜰의 문, 벽, 바닥을 함께 보여줍니다. 관객이 공간을 처음 보는 장면이나 인물이 어디로 이동할지 알려줄 때 유용합니다. 여기서 중요한 것은 얼굴 표정보다 인물과 주변 공간의 관계입니다.','The first example includes the full figure, shoes, doorway, walls and courtyard ground. This is useful when introducing a location or showing where someone can move. The relationship between the person and the space matters more than fine facial expression.',
    '프롬프트에는 “원경”만 적기보다 “머리부터 신발까지, 안뜰의 문과 바닥이 함께 보이는 넓은 구도”라고 화면에 남길 정보를 적어 보세요. 인물을 너무 작게 만들면 행동을 읽기 어려워질 수 있습니다.','Instead of writing only “wide shot,” specify what stays visible: “head to shoes, with the courtyard doorway and ground.” Making the figure too small can make the action hard to read.'),
    ('02 / MEDIUM','중경: 무엇을 하는지 보여줍니다.','Medium: show what the character does.',
    '두 번째 예시는 허리 위 인물과 손에 든 편지가 함께 보입니다. 대화나 물건을 건네는 행동처럼 얼굴과 손을 동시에 읽어야 할 때 출발점으로 삼기 좋습니다. 원경보다 배경 정보는 줄고, 행동의 의미는 더 잘 보입니다.','The second example shows the character from the waist up, including the letter in her hands. It is a useful starting point for dialogue or handing over an object, when both face and hands need to be readable. It reveals less environment than the wide shot and more detail in the action.',
    '“허리 위 중경, 손과 편지가 화면 아래에 모두 보임”처럼 필요한 소품도 지정하세요. 손이 프레임 밖으로 빠지면 편지를 건넨다는 행동이 전달되지 않습니다.','Specify important props too: “waist-up medium shot, both hands and the letter visible near the lower frame.” If the hands disappear outside the frame, the handover may no longer read.'),
    ('03 / CLOSE-UP','근경: 어떻게 느끼는지 보여줍니다.','Close-up: reveal how the character feels.',
    '세 번째 예시는 얼굴과 어깨가 화면 대부분을 차지합니다. 편지의 내용이나 누군가의 말에 반응하는 눈과 입, 작은 표정 변화를 보여주고 싶을 때 사용해 보세요. 주변 공간은 흐려지지만 감정은 더 가까이 읽힙니다.','The third example fills most of the frame with face and shoulders. Try it when you want to show the eyes, mouth or a restrained reaction to the letter or another person’s words. The surrounding space becomes less prominent while the expression reads more closely.',
    '근경이 항상 더 감동적인 것은 아닙니다. 관객이 사건을 이해하기 전에 얼굴만 크게 보여주면 상황이 모호해질 수 있습니다. 의미 있는 반응을 강조할 컷에 선택해서 쓰세요.','A close-up is not automatically more emotional. If the audience sees only a face before understanding the event, the situation can remain unclear. Choose it when a reaction needs emphasis.'),
    ]
    blocks=[]
    for label,ko,en,a,b,c,d in steps:
        blocks.append(f'<section class="tutorial-step"><span class="tutorial-number">{label[:2]}</span><div><p class="section-eyebrow">{label}</p><h2>{t(ko,en)}</h2><p>{t(a,b)}</p><details class="tutorial-explain"><summary>{t("프롬프트에 적는 방법","How to specify the frame")}</summary><p>{t(c,d)}</p></details></div></section>')
    prompts=[
    ('원경 실습','Wide-shot exercise','첨부한 기준 시트와 같은 가상의 성인 여성입니다. 얼굴·머리·버건디 드레스와 손에 든 봉인된 편지를 유지합니다. 흐린 낮, 오래된 저택의 돌 안뜰에 가만히 서서 문 쪽을 바라봅니다. 눈높이 카메라의 넓은 구도. 머리부터 신발까지 전체 인물이 보이고, 문·돌벽·바닥이 함께 보입니다. 자연스러운 피부와 절제된 색감. 카메라 움직임 없이 정지된 씬 이미지입니다.','Use the same fictional adult woman as the attached reference. Preserve face, hair, burgundy dress and the sealed letter in her hands. She stands still in the stone courtyard of an old manor on an overcast day, looking toward the doorway. Eye-level wide framing. Show her full figure from head to shoes, plus the doorway, walls and ground. Natural skin and restrained color. A still scene image with no camera movement.'),
    ('중경 실습','Medium-shot exercise','첨부한 기준 시트와 같은 인물·의상·편지·장소·흐린 낮 조명을 유지합니다. 눈높이 카메라, 허리 위가 보이는 중경. 손 두 개와 봉인된 편지를 화면 아래쪽에 모두 포함하고 머리 위에는 약간의 여백을 둡니다. 문 쪽으로 향한 시선과 차분한 표정을 유지합니다. 정지 씬 이미지이며 카메라 이동이나 줌은 없습니다.','Keep the same reference identity, clothes, letter, courtyard and overcast daylight. Use an eye-level waist-up medium shot. Include both hands and the sealed letter near the lower frame, leaving a little room above the head. Preserve the gaze toward the doorway and restrained expression. A still image, with no camera move or zoom.'),
    ('근경 실습','Close-up exercise','첨부한 기준 시트와 같은 인물·머리·의상·장소·흐린 낮 조명을 유지합니다. 눈높이 카메라, 얼굴과 어깨가 보이는 근경. 눈과 입의 미세한 긴장감이 읽히고 시선은 앞선 컷과 같은 방향입니다. 배경 안뜰은 부드럽게 흐려지며 피부를 과하게 보정하지 않습니다. 손과 편지는 화면 밖입니다. 정지 씬 이미지입니다.','Keep the same reference identity, hair, clothes, courtyard and overcast daylight. Use an eye-level face-and-shoulders close-up. Make restrained tension in eyes and mouth readable, keeping the gaze in the same direction as the earlier shot. Let the courtyard background soften; avoid heavy skin retouching. Hands and letter stay outside this framing. A still scene image.'),
    ]
    prompt_blocks=''.join(f'<details class="tutorial-prompt"><summary>{t(ko,en)} · {t("전체 프롬프트","Complete prompt")}</summary><pre tabindex="0"><code>{t(pko,pen)}</code></pre></details>' for ko,en,pko,pen in prompts)
    figure=f'<figure class="tutorial-figure"><a href="{ART}" target="_blank" rel="noopener"><img src="{ART}" width="1672" height="941" alt="{t("같은 안뜰 인물의 원경·중경·근경 비교","Wide, medium and close-up comparison of one courtyard character")}" decoding="async" fetchpriority="high"></a><figcaption>{t("이 강좌를 위해 새로 만든 AI 구도 설명 이미지입니다. 같은 카메라로 실제 촬영한 비교나 특정 플랫폼의 생성 성능 실험은 아닙니다. 이미지를 누르면 크게 볼 수 있습니다.","New AI illustrations for this lesson, not frames from a controlled camera shoot or a test of any platform’s generation performance. Select the image to view it larger.")}</figcaption></figure>'
    practical=f'''<section class="tutorial-scenes"><h2>{t('첫 실습은 세 장으로 충분합니다.','Three frames are enough for a first exercise.')}</h2><p>{t('기준 시트를 실제로 첨부한 다음 아래 프롬프트를 한 장씩 시험하세요. 인물과 의상·장소·빛은 유지하고 화면에 보이는 범위만 바꿉니다. 도구의 참고 이미지 입력과 비율 설정은 현재 화면을 따르세요.','Attach your actual reference sheet and try the prompts one image at a time. Keep identity, clothes, location and light; change only the visible framing. Use the reference-input and aspect-ratio controls available in your tool.')}</p>{prompt_blocks}</section><section class="tutorial-scenes"><h2>{t('세 컷을 이어 붙이기 전에','Before connecting the three shots')}</h2><p>{t('원경→중경→근경은 따라 해보기 쉬운 순서일 뿐, 모든 장면의 정답은 아닙니다. 공간 소개가 이미 끝났다면 중경부터 시작해도 됩니다. 손에 있던 편지가 다음 컷에서 사라지거나 시선 방향이 반대로 바뀌지 않았는지 먼저 확인하세요.','Wide → medium → close-up is an easy practice sequence, not a rule for every scene. If the location is already established, start with a medium shot. Check that the letter does not disappear between relevant shots and that gaze direction does not unexpectedly reverse.')}</p><p>{t('샷 크기와 카메라 움직임도 별개입니다. 중경을 쓰면서 카메라를 고정할 수 있고, 원경에서 천천히 전진할 수도 있습니다. 처음에는 정지 구도로 이해한 뒤 움직임을 추가하세요.','Shot size and camera motion are separate decisions. A medium shot can use a locked camera; a wide shot can include a slow push. Understand the still framing first, then add motion.')}</p></section>'''
    ending=f'''<aside class="tutorial-ending"><h2>{t('다음에는 이 구도를 움직여 봅니다.','Next, bring this framing into motion.')}</h2><div class="tutorial-actions"><a class="button button-white" href="/tutorials/seedance-2-5/">{t('시댄스 영상화 실습','Seedance animation exercise')} →</a><a class="button button-glass" href="/tutorials/character-sheet/">{t('캐릭터 기준부터 만들기','Create a character reference')} →</a><a class="text-button" href="/questions/">{t('구도에 대해 질문하기','Ask about framing')} →</a></div></aside>'''
    body=f'<body class="watch-page">{header()}<main class="tutorial-main" id="main"><a class="note-back" href="/tutorials/">← {t("튜토리얼 목록","All tutorials")}</a><p class="section-eyebrow">CAMERA / FRAMING / FIRST EXERCISE</p><h1>{title}</h1><p class="tutorial-intro">{t("구도를 고를 때는 렌즈 이름보다 먼저, 관객에게 무엇을 보여줄지 정합니다. 같은 인물과 장소를 공간·행동·감정 세 가지 기준으로 살펴보세요.","Before choosing a lens label, decide what the audience needs to see. Explore one character and location through space, action and emotion.")}</p><p class="tutorial-date"><time datetime="2026-10-12">2026.10.12</time> · {t("초보자 실습 · 정지 씬부터","Beginner exercise · Start with still frames")}</p>{figure}{"".join(blocks)}{practical}{ending}</main>{footer()}</body></html>'
    schema={'@context':'https://schema.org','@type':'Article','headline':title,'description':desc,'url':origin+PATH,'image':origin+ART,'datePublished':'2026-10-12','dateModified':'2026-10-12','author':{'@type':'Organization','name':'DRA9ON CINEMA'}}
    t(TITLE_KO+' | DRA9ON CINEMA',TITLE_EN+' | DRA9ON CINEMA')
    target=out/PATH.strip('/');target.mkdir(parents=True,exist_ok=True)
    (target/'index.html').write_text(head(title+' | DRA9ON CINEMA',desc,PATH,schema).replace('property="og:type" content="video.episode"','property="og:type" content="article"')+body,encoding='utf-8')
